{"file_path":"tests/test_metrics.py","content":"from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_is_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_each_session_equally():
    groups = {
        "large": [{"converted": True}] + [{"converted": False}] * 9,
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.2
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 5) == 3
    assert conversions_in_window([1, 2], 0) == 0


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_values_whitespace_and_skips():
    assert parse_session_log([
        "  # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_report_input_line_number():
    try:
        parse_session_log(["# skipped", "x1,nope,1"])
    except ValueError as exc:
        assert "line 2" in str(exc)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_sessions_keeps_last_duplicate_id():
    first = {"id": "same", "day": 1, "converted": False}
    replacement = {"id": "same", "day": 3, "converted": True}
    other = {"id": "other", "day": 2, "converted": False}
    assert dedupe_sessions([first, other, replacement]) == [other, replacement]


def test_dedupe_sessions_sorts_by_day_then_id():
    events = [
        {"id": "b", "day": 1, "converted": False},
        {"id": "a", "day": 1, "converted": True},
    ]
    assert [event["id"] for event in dedupe_sessions(events)] == ["a", "b"]


def test_daily_conversion_counts_inclusive_range():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": None},
        {"id": "c", "day": 2, "converted": True},
        {"id": "d", "day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 4) == [1, 0, 1]
    assert daily_conversion_counts(events, 5, 4) == []


def test_campaign_summary():
    groups = {
        "converted": [{"id": "a", "day": 1, "converted": True}],
        "empty": [],
        "not-converted": [{"id": "b", "day": 3, "converted": False}],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "a": [{"converted": True}],
        "middle": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]


def test_conversion_rate_by_group_sorted_with_none_for_empty():
    assert conversion_rate_by_group({"z": [], "a": [{"converted": None}]}) == {
        "a": 0.0,
        "z": None,
    }


def test_longest_conversion_streak():
    assert longest_conversion_streak([2, 1, 0, 3, 4]) == 2
    assert longest_conversion_streak([]) == 0
